urlset:
{% for post in posts %}
{% if post.layout == 'post' or post.path == 'about/index.html' or post.path == 'archives/index.html' or post.path == 'photography/index.html' or post.path == 'links/index.html' or post.path == 'categories/index.html' %}

  {{ post.permalink | uriencode }}
  {% if post.updated %}
  {{ post.updated | formatDate }}
  {% elif post.date %}
  {{ post.date | formatDate }}
  {% endif %}
  monthly
  0.6

{% endif %}
{% endfor %}


  {{ config.url }}/
  daily
  1.0
